Write the file /Users/bussss/projects/twenty-playground/pn-add-entities.mjs with exactly this content:
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import { randomUUID as u } from 'node:crypto';

const write = (path, source) => {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, source);
};
const nameFieldId = u();

write('src/objects/pn-case.object.ts', `import { defineObject, FieldType } from 'twenty-sdk/define';

export default defineObject({
  universalIdentifier: '${u()}',
  nameSingular: 'pnCase',
  namePlural: 'pnCases',
  labelSingular: 'PN Case',
  labelPlural: 'PN Cases',
  icon: 'IconBox',
  labelIdentifierFieldMetadataUniversalIdentifier: '${nameFieldId}',
  fields: [
    { universalIdentifier: '${nameFieldId}', type: FieldType.TEXT, name: 'name', label: 'Name', icon: 'IconAbc' },
  ],
});
`);

write('src/fields/pn-company-risk-note.field.ts', `import { defineField, FieldType, STANDARD_OBJECT_UNIVERSAL_IDENTIFIERS } from 'twenty-sdk/define';

export default defineField({
  universalIdentifier: '${u()}',
  objectUniversalIdentifier: STANDARD_OBJECT_UNIVERSAL_IDENTIFIERS.company.universalIdentifier,
  type: FieldType.TEXT,
  name: 'pnRiskNote',
  label: 'PN Risk Note',
  icon: 'IconAbc',
});
`);

write('src/logic-functions/pn-hello-route.ts', `import { defineLogicFunction } from 'twenty-sdk/define';

const handler = async (): Promise<{ message: string }> => ({ message: 'PN hello' });

export default defineLogicFunction({
  universalIdentifier: '${u()}',
  name: 'pn-hello-route',
  description: 'PN scratch route',
  timeoutSeconds: 10,
  handler,
  httpRouteTriggerSettings: { path: '/pn-hello', httpMethod: 'GET', isAuthRequired: false },
});
`);

write('src/logic-functions/pn-echo-tool.ts', `import { defineLogicFunction } from 'twenty-sdk/define';

const handler = async (params: { text: string }): Promise<{ echoed: string }> => ({ echoed: params.text });

export default defineLogicFunction({
  universalIdentifier: '${u()}',
  name: 'pn-echo-tool',
  description: 'PN scratch tool: echoes the given text back',
  timeoutSeconds: 10,
  handler,
  toolTriggerSettings: {
    inputSchema: {
      type: 'object',
      properties: { text: { type: 'string', description: 'Text to echo' } },
      required: ['text'],
    },
  },
});
`);

write('src/logic-functions/pn-env-probe.ts', `import { defineLogicFunction } from 'twenty-sdk/define';

const handler = async () => ({
  hasAppSecret: 'APP_SECRET' in process.env,
  hasPgUrl: 'PG_DATABASE_URL' in process.env,
  apiUrl: process.env.TWENTY_API_URL ?? null,
});

export default defineLogicFunction({
  universalIdentifier: '${u()}',
  name: 'pn-env-probe',
  description: 'PN scratch probe: reports which env var names exist, never values',
  timeoutSeconds: 10,
  handler,
});
`);
